-- =====================================================================-- EduSync Pro — Migration 0002 : EduSync Knowledge (bibliothèque numérique)-- =====================================================================-- Objet : créer la bibliothèque numérique scolaire par établissement.-- Tables :--   • knowledge_resources  → catalogue documentaire (locales + réf. externes)--   • knowledge_history    → historique de consultation---- CONSIGNES :--   • Base locale uniquement (127.0.0.1:5432/app_db).--   • Idempotent (sûr à relancer).--   • Ne supprime aucune donnée existante.--   • Le schéma `demo` est dupliqué automatiquement à l'accès (ensureDemoSchema),--     mais on crée aussi ici la table demoséquipée pour éviter tout délai.-- =====================================================================CREATE TABLE IF NOT EXISTS "public"."knowledge_resources" (  "id" text PRIMARY KEY,  "title" text NOT NULL,  "subtitle" text,  "authors" text,  "isbn" text,  "publisher" text,  "publication_year" integer,  "edition" text,  "subject" text,  "level" text,  "class_level" text,  "language" text DEFAULT 'fr',  "country" text,  "region" text,  "education_system" text,  "curriculum" text,  "description" text,  "cover_url" text,  "resource_type" text,  "source_type" text,  "source_name" text,  "source_url" text,  "external_id" text,  "access_mode" text,  "rights_status" text,  "license" text,  "file_url" text,  "scope" text DEFAULT 'ESTABLISHMENT',  "school_id" text,  "status" text DEFAULT 'active',  "created_by" text,  "last_verified_at" text,  "created_at" text,  "updated_at" text);CREATE INDEX IF NOT EXISTS "knowledge_resources_school_idx"  ON "public"."knowledge_resources" ("school_id");CREATE INDEX IF NOT EXISTS "knowledge_resources_subject_idx"  ON "public"."knowledge_resources" ("subject");CREATE INDEX IF NOT EXISTS "knowledge_resources_level_idx"  ON "public"."knowledge_resources" ("level");CREATE INDEX IF NOT EXISTS "knowledge_resources_scope_idx"  ON "public"."knowledge_resources" ("scope");CREATE INDEX IF NOT EXISTS "knowledge_resources_access_idx"  ON "public"."knowledge_resources" ("access_mode");CREATE TABLE IF NOT EXISTS "public"."knowledge_history" (  "id" text PRIMARY KEY,  "user_id" text NOT NULL,  "resource_id" text NOT NULL,  "school_id" text,  "action" text NOT NULL,  "created_at" text NOT NULL);CREATE INDEX IF NOT EXISTS "knowledge_history_user_idx"  ON "public"."knowledge_history" ("user_id", "created_at");CREATE INDEX IF NOT EXISTS "knowledge_history_resource_idx"  ON "public"."knowledge_history" ("resource_id");-- Duplication du schéma démo (cohérence immédiate avec ensureDemoSchema).CREATE TABLE IF NOT EXISTS "demo"."knowledge_resources" (LIKE "public"."knowledge_resources" INCLUDING ALL);CREATE TABLE IF NOT EXISTS "demo"."knowledge_history" (LIKE "public"."knowledge_history" INCLUDING ALL);